#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# KSUX-specific helpers live BELOW the unchanged upstream library.
# Source: https://github.com/mattpocock/skills/tree/main/skills/engineering/wizard
fail() { warn "$1"; exit 1; }

# Do not source dotenv files. Restrict inputs to single-line, literal-safe values;
# the upstream writer uses shell-style quotes, not a general dotenv serializer.
capture() {
  local key="$1" prompt="$2" secret="${3:-public}" value
  while true; do
    if [[ "$secret" == secret ]]; then ask_secret "$key" "$prompt"; else ask "$key" "$prompt"; fi
    value="${!key}"
    if [[ -z "$value" || "$value" == *[$'\r\n\t']* || "$value" == *"'"* || "$value" == *'"'* || "$value" == *'\'* || "$value" == *'$'* || "$value" == *'`'* ]]; then
      warn "Enter a nonempty, single-line literal value without quotes, backslashes or shell expansions."
      continue
    fi
    write_env "$key" "$value"
    return
  done
}

optional_service() {
  local key="$1" label="$2" choice=no
  if confirm "$label (No leaves existing remote settings unchanged)"; then choice=yes; fi
  write_env "$key" "$choice"
  [[ "$choice" == yes ]]
}

convex_prod() {
  # The explicit production key overrides any development selection in .env.local.
  # Never pass credentials as command-line arguments or enable shell tracing.
  (
    unset CONVEX_DEPLOYMENT CONVEX_SELF_HOSTED_URL CONVEX_SELF_HOSTED_ADMIN_KEY CONVEX_AGENT_MODE
    export CONVEX_DEPLOY_KEY
    ./node_modules/.bin/convex "$@"
  )
}

set_convex() {
  local key="$1"
  if ! printf '%s' "${!key}" | convex_prod env set "$key" >/dev/null 2>&1; then
    fail "Convex rejected $key. Check deployment permissions; re-run to retry. No credential output was printed."
  fi
  note "Set Convex production: $key"
}

set_vercel() {
  local key="$1" kind="${2:-public}" sensitivity=--no-sensitive
  [[ "$kind" != secret ]] || sensitivity=--sensitive
  if ! printf '%s' "${!key}" | vercel env add "$key" --environment production --project "$VERCEL_PROJECT_ID" --scope "$VERCEL_TEAM_ID" --force --yes "$sensitivity" >/dev/null 2>&1; then
    fail "Vercel rejected $key. Check CLI login and project scope; re-run to retry."
  fi
  note "Set Vercel Production only: $key"
}

run_wizard() {
# Stop inherited xtrace before any secret is entered. Never run with bash -v.
set +x
TOTAL_STAGES=12
local root project_meta key prefix expected_url pair
root="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd -P)"
cd "$root"
[[ -t 0 && -t 1 ]] || fail "Run this wizard directly in an interactive terminal, not through the agent or a pipe."
command -v node >/dev/null 2>&1 || fail "Install Node.js 22+ first."
command -v pnpm >/dev/null 2>&1 || fail "Install pnpm first."
command -v vercel >/dev/null 2>&1 || fail "Install the Vercel CLI and run vercel login first."
[[ -x node_modules/.bin/convex ]] || fail "Run pnpm install before starting this wizard."
command -v git >/dev/null 2>&1 || fail "Git is required to verify the secret file is ignored."

# Deliberately separate from .env.local and Next.js's production env filenames.
# The path is fixed: never follow a caller-supplied ENV_FILE or a symlink.
ENV_FILE="$root/.env.production-setup"
[[ ! -L "$ENV_FILE" ]] || fail "Refusing a symlink at .env.production-setup."
[[ ! -e "$ENV_FILE" || -f "$ENV_FILE" ]] || fail "Secret state path must be a regular file."
if git ls-files --error-unmatch .env.production-setup >/dev/null 2>&1; then
  fail "The production state file is tracked by Git. Remove it from the index and rotate exposed credentials first."
fi
git check-ignore -q .env.production-setup || fail "Ignore .env.production-setup in Git before proceeding."
umask 077
: >> "$ENV_FILE"
chmod 600 "$ENV_FILE"

banner "KSUX · full production setup"
warn "Credentials are saved as plaintext with mode 0600 in .env.production-setup. This is NOT an encrypted password vault."
say "Your .env.local is untouched. No GitHub secrets, paid upgrades, or custom domains are created."
say "Optional skips preserve existing remote credentials; they do NOT disable an already-configured service."
pause "Press Enter after reading the safety notes."

stage "Vercel: verify the existing project and account"
vercel whoami || fail "Run vercel login in your terminal, then restart."
[[ -f .vercel/project.json ]] || fail "Run vercel link for the intended existing KSUX project, then restart."
project_meta="$(node --input-type=module -e 'import fs from "node:fs"; const p=JSON.parse(fs.readFileSync(".vercel/project.json","utf8")); if(!/^prj_[A-Za-z0-9]+$/.test(p.projectId)||!/^team_[A-Za-z0-9]+$/.test(p.orgId)) process.exit(1); console.log(p.projectId+" "+p.orgId);')" || fail "Invalid Vercel project metadata."
read -r VERCEL_PROJECT_ID VERCEL_TEAM_ID <<< "$project_meta"
export VERCEL_PROJECT_ID VERCEL_TEAM_ID
say "Target project: $VERCEL_PROJECT_ID; team: $VERCEL_TEAM_ID"
vercel api "/v9/projects/$VERCEL_PROJECT_ID?teamId=$VERCEL_TEAM_ID" --scope "$VERCEL_TEAM_ID" | node --input-type=module -e 'let s="";for await(const c of process.stdin)s+=c;const p=JSON.parse(s);if(p.id!==process.env.VERCEL_PROJECT_ID||p.accountId!==process.env.VERCEL_TEAM_ID)process.exit(1);console.log("  Verified project: "+p.name);' || fail "Could not verify the owning Vercel team and project."
open_url "https://vercel.com/dashboard"
step "Open the verified KSUX project. Settings → Git: verify Control707/KSUX and production branch main."
step "Review the current plan and usage limits; stay on free tiers. Do not enable paid services."
confirm "Is this the correct production project and Git connection" || fail "Cancelled before remote changes."

stage "Convex: production deployment and deploy key"
open_url "https://dashboard.convex.dev"
step "Open/create the ksux project on the free plan, then select its Production deployment."
step "Deployment Settings → General → Generate Production Deploy Key. Include deployment:deploy."
note "This wizard also needs permission to manage environment variables and run the seed; use an appropriately authorized production key."
capture CONVEX_DEPLOY_KEY "Paste the Production Deploy Key (hidden):" secret
prefix="${CONVEX_DEPLOY_KEY%%|*}"
[[ "$CONVEX_DEPLOY_KEY" == prod:*'|'?* && "$prefix" =~ ^prod:[a-z0-9-]+$ ]] || fail "Expected a production deployment key, not a dev, preview, or project key."
capture NEXT_PUBLIC_CONVEX_URL "Copy the Production deployment URL (https://...convex.cloud):"
expected_url="https://${prefix#prod:}.convex.cloud"
[[ "$NEXT_PUBLIC_CONVEX_URL" == "$expected_url" ]] || fail "URL does not match the production deployment named by the deploy key."
capture NEXT_PUBLIC_CONVEX_SITE_URL "Copy its HTTP Actions URL (https://...convex.site):"
[[ "$NEXT_PUBLIC_CONVEX_SITE_URL" == "https://${prefix#prod:}.convex.site" ]] || fail "HTTP Actions URL does not match the same production deployment."
say "Convex production target: $NEXT_PUBLIC_CONVEX_URL"
confirm "Use this Convex production deployment for all remaining writes" || fail "Cancelled."

stage "UploadThing: shared production upload token"
open_url "https://uploadthing.com/dashboard"
step "Open/create the KSUX app on the free plan. Copy its SDK token, named UPLOADTHING_TOKEN."
note "Dashboard labels can change: use https://docs.uploadthing.com/getting-started/appdir if the token is not visible."
capture UPLOADTHING_TOKEN "Paste UPLOADTHING_TOKEN (hidden):" secret
say "The same token will be installed in Vercel and Convex (uploads and cleanup)."

stage "Gmail: production OTP delivery"
open_url "https://myaccount.google.com/security"
step "Sign in as the sending Gmail account; enable 2-Step Verification if it is not already enabled."
open_url "https://myaccount.google.com/apppasswords"
step "Create an app password named KSUX. If unavailable, check your account/admin policy; do not use your normal password."
capture GMAIL_SMTP_USER "Sending Gmail address:"
capture GMAIL_SMTP_APP_PASSWORD "Paste the 16-character app password without display spaces (hidden):" secret
[[ "$GMAIL_SMTP_USER" == *@* && "$GMAIL_SMTP_APP_PASSWORD" =~ ^[A-Za-z0-9]{16}$ ]] || fail "Expected an email address and a 16-character app password (remove spaces)."
if optional_service SETUP_GMAIL_FALLBACK "Configure a second Gmail sender for quota fallback"; then
  open_url "https://myaccount.google.com/apppasswords"
  step "Switch to the second account and create its own KSUX app password with 2-Step Verification enabled."
  capture GMAIL_SMTP_FALLBACK_USER "Fallback Gmail address:"
  capture GMAIL_SMTP_FALLBACK_APP_PASSWORD "Fallback app password without spaces (hidden):" secret
  [[ "$GMAIL_SMTP_FALLBACK_USER" == *@* && "$GMAIL_SMTP_FALLBACK_APP_PASSWORD" =~ ^[A-Za-z0-9]{16}$ ]] || fail "Invalid fallback sender/app-password format."
fi
write_env KSUX_ALLOW_DEV_OTP_LOG false
note "Production OTP logging will explicitly be disabled."

stage "Groq: privacy controls and primary AI key"
open_url "https://console.groq.com/settings/data-controls"
step "For the intended organization, enable Zero Data Retention for inference/system reliability and abuse monitoring."
confirm "Have you enabled and verified Groq Zero Data Retention" || fail "Enable ZDR before configuring the primary AI service."
open_url "https://console.groq.com/keys"
step "Create a KSUX API key in that same organization, then copy it."
capture GROQ_API_KEY "Paste GROQ_API_KEY (hidden):" secret

stage "Gemini: optional AI fallback"
if optional_service SETUP_GEMINI "Configure Gemini fallback"; then
  open_url "https://aistudio.google.com/api-keys"
  step "Create/select a project, create an API key, and confirm free-tier availability before enabling it."
  note "If billing is required, skip this service rather than enrolling in a paid plan."
  capture GEMINI_API_KEY "Paste GEMINI_API_KEY (hidden):" secret
fi

stage "Cloudflare: optional Workers AI fallback"
if optional_service SETUP_CLOUDFLARE "Configure Cloudflare Workers AI"; then
  open_url "https://dash.cloudflare.com/?to=/:account/ai/workers-ai"
  step "Select the intended account → Workers AI → Use REST API."
  step "Create a Workers AI API Token → review scope → Create API Token → Copy API Token."
  capture CLOUDFLARE_API_TOKEN "Paste Workers AI token (hidden):" secret
  step "Under Get Account ID, copy Account ID for that same account."
  capture CLOUDFLARE_ACCOUNT_ID "Paste Cloudflare Account ID:"
  [[ "$CLOUDFLARE_ACCOUNT_ID" =~ ^[a-fA-F0-9]{32}$ ]] || fail "Expected a 32-character hexadecimal account ID."
fi

stage "Web Push: optional VAPID keys"
if optional_service SETUP_WEB_PUSH "Configure Web Push"; then
  if [[ -n "$(_existing VAPID_PRIVATE_KEY || true)" ]]; then
    step "Keep your existing keypair: changing it can invalidate existing push subscriptions."
    capture NEXT_PUBLIC_VAPID_PUBLIC_KEY "Public VAPID key (Enter keeps current):"
    capture VAPID_PRIVATE_KEY "Private VAPID key (Enter keeps current; hidden):" secret
  else
    if confirm "Generate a new VAPID keypair locally (no external service)"; then
      pair="$(node --input-type=module -e 'import webpush from "web-push";const k=webpush.generateVAPIDKeys();console.log(k.publicKey+":"+k.privateKey);')"
      write_env NEXT_PUBLIC_VAPID_PUBLIC_KEY "${pair%%:*}"
      write_env VAPID_PRIVATE_KEY "${pair#*:}"
      unset pair
    else
      capture NEXT_PUBLIC_VAPID_PUBLIC_KEY "Existing public VAPID key:"
      capture VAPID_PRIVATE_KEY "Existing private VAPID key (hidden):" secret
    fi
  fi
  # Verify both syntax and that the public key belongs to the private key.
  printf '%s\n%s\n' "$NEXT_PUBLIC_VAPID_PUBLIC_KEY" "$VAPID_PRIVATE_KEY" | node --input-type=module -e 'import{createECDH}from"node:crypto";let s="";for await(const c of process.stdin)s+=c;const[p,k]=s.trim().split("\n");const e=createECDH("prime256v1");e.setPrivateKey(Buffer.from(k,"base64url"));if(e.getPublicKey().toString("base64url")!==p)process.exit(1);' || fail "The VAPID public/private keys do not form a valid pair."
  capture VAPID_SUBJECT "Push contact (mailto:your-email or https://your-site):"
  [[ "$VAPID_SUBJECT" == mailto:*@* || "$VAPID_SUBJECT" == https://?* ]] || fail "Expected a mailto: contact or HTTPS URL."
fi

stage "Maintainer: production moderation access"
step "Use the exact canonical KSU email addresses of authorized production moderators."
note "Keep each actual domain (@students.kennesaw.edu or @kennesaw.edu); remove +aliases."
capture KSUX_MAINTAINER_EMAILS "Comma-separated canonical KSU maintainer emails (no spaces):"
printf '%s' "$KSUX_MAINTAINER_EMAILS" | node --input-type=module -e 'let s="";for await(const c of process.stdin)s+=c;if(!s.split(",").every(e=>/^[a-z0-9._-]+@(students\.)?kennesaw\.edu$/.test(e)))process.exit(1);' || fail "Use lowercase KSU addresses without +aliases, separated by commas."

stage "Review targets and apply production environment"
say "Vercel project: $VERCEL_PROJECT_ID; team: $VERCEL_TEAM_ID (Production only)."
say "Convex: $NEXT_PUBLIC_CONVEX_URL"
say "Required: Convex URLs/key, UploadThing, primary Gmail, Groq, OTP logging=false, maintainers."
say "Optional selections: Gmail fallback=$SETUP_GMAIL_FALLBACK; Gemini=$SETUP_GEMINI; Cloudflare=$SETUP_CLOUDFLARE; Push=$SETUP_WEB_PUSH."
warn "This replaces matching production environment values. Writes are sequential, not transactional; stop on failure and rerun."
confirm "Apply these settings to BOTH verified production targets now" || fail "Nothing applied. Captured values remain in the private state file."
for key in GMAIL_SMTP_USER GMAIL_SMTP_APP_PASSWORD GROQ_API_KEY UPLOADTHING_TOKEN KSUX_ALLOW_DEV_OTP_LOG KSUX_MAINTAINER_EMAILS; do set_convex "$key"; done
if [[ "$SETUP_GMAIL_FALLBACK" == yes ]]; then
  for key in GMAIL_SMTP_FALLBACK_USER GMAIL_SMTP_FALLBACK_APP_PASSWORD; do set_convex "$key"; done
fi
if [[ "$SETUP_GEMINI" == yes ]]; then set_convex GEMINI_API_KEY; fi
if [[ "$SETUP_CLOUDFLARE" == yes ]]; then
  for key in CLOUDFLARE_ACCOUNT_ID CLOUDFLARE_API_TOKEN; do set_convex "$key"; done
fi
if [[ "$SETUP_WEB_PUSH" == yes ]]; then
  for key in NEXT_PUBLIC_VAPID_PUBLIC_KEY VAPID_PRIVATE_KEY VAPID_SUBJECT; do set_convex "$key"; done
  set_vercel NEXT_PUBLIC_VAPID_PUBLIC_KEY
fi
set_vercel NEXT_PUBLIC_CONVEX_URL
set_vercel NEXT_PUBLIC_CONVEX_SITE_URL
set_vercel UPLOADTHING_TOKEN secret
set_vercel CONVEX_DEPLOY_KEY secret
# Read back only non-secrets, never decrypt or print credentials.
for key in KSUX_ALLOW_DEV_OTP_LOG KSUX_MAINTAINER_EMAILS; do
  [[ "$(convex_prod env get "$key")" == "${!key}" ]] || fail "Convex verification failed for $key."
done

stage "Vercel: build settings and production deployment"
open_url "https://vercel.com/dashboard"
step "Open the verified KSUX project → Settings → Build and Deployment."
step "Override Build Command with: npx convex deploy --cmd-url-env-var-name NEXT_PUBLIC_CONVEX_URL --cmd 'pnpm build'"
step "Keep the Next.js framework preset and repository-root Root Directory; save the settings."
warn "Production credentials must NOT be available to Preview/Development builds or untrusted pull requests."
step "Settings → Environment Variables: verify the new values are Production-only."
step "Do not deploy previews until a separate Convex preview key/backend is configured."
confirm "Have you saved the build settings and checked production-only credential scope" || fail "Settings not confirmed; deploy remains pending."
warn "Deployment will change the live frontend and Convex schema/functions. Review the main branch first."
if confirm "Ready to deploy the reviewed main branch to production in the dashboard"; then
  step "Deploy the main branch in Vercel (or redeploy its latest deployment); wait until Ready."
  note "Redeploy after changing env vars: existing deployments do not pick them up automatically."
  pause "Press Enter once the deployment has finished."
  confirm "Does Vercel show Ready with a successful Convex deployment in the build logs" || fail "Deployment not verified. Inspect the build logs before continuing."
else
  fail "Production deployment left pending. Settings are saved; rerun when ready."
fi

stage "Seed production and run live checks"
warn "The bootstrap writes institutional catalog data to the production database; take a backup for an existing populated deployment."
if confirm "Run the idempotent production seed:bootstrapKsu now"; then
  convex_prod run --prod seed:bootstrapKsu
else
  SKIPPED+=("Production seed:bootstrapKsu was not run; catalogs may be missing.")
fi
note "seed:backfillEmbeddings currently returns ready/embeddedCount=0; it does NOT generate vectors."
step "Copy the production .vercel.app origin from the verified Vercel project."
capture KSUX_PRODUCTION_URL "Production origin (https://...vercel.app, no trailing slash):"
[[ "$KSUX_PRODUCTION_URL" =~ ^https://[a-zA-Z0-9-]+\.vercel\.app$ ]] || fail "Expected an HTTPS .vercel.app origin with no path."
open_url "$KSUX_PRODUCTION_URL/?demo=1"
step "Check demo login, both campuses, Feed, a two-tab chat, and Ask Scrappy."
step "Outside demo mode, request a real KSU email OTP; verify delivery and successful login."
step "As a real user, upload an image and verify maintainer moderation access."
if [[ "$SETUP_WEB_PUSH" == yes ]]; then step "On an installed supported PWA, opt into Push and verify delivery."; fi
if ! confirm "Have the live production smoke checks passed"; then
  SKIPPED+=("Live smoke checks not confirmed; do not consider production ready.")
fi
finish
warn "The private .env.production-setup file still contains production secrets. Keep it secure, or remove it manually after saving required credentials safely."
say "No Git commit was created. No new server was started. Re-running offers saved values and re-confirms production writes."
}

run_wizard "$@"; exit

